import{_ as p,r as a,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"AJAX - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как использовать AJAX в панели управления.","frontmatter":{"subtitle":"Узнайте, как использовать AJAX в панели управления."},"headers":[{"level":2,"title":"AJAX-обработчики панели управления","slug":"ajax-обработчики-панели-управления","link":"#ajax-обработчики-панели-управления","children":[{"level":3,"title":"Вызов AJAX-запросов","slug":"вызов-ajax-запросов","link":"#вызов-ajax-запросов","children":[]}]},{"level":2,"title":"AJAX-обработчики поведений","slug":"ajax-обработчики-поведении","link":"#ajax-обработчики-поведении","children":[]},{"level":2,"title":"AJAX-обработчики виджетов","slug":"ajax-обработчики-виджетов","link":"#ajax-обработчики-виджетов","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/extend/system/ajax.md","filePath":"3.x/ru/extend/system/ajax.md"}'),i={name:"3.x/ru/extend/system/ajax.md"};function r(k,n,d,g,h,m){const t=a("pre-heading"),e=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"AJAX",-1)),s(e),n[1]||(n[1]=u(`<p>Панель управления использует ту же <a href="./../../cms/ajax/introduction.html">AJAX-библиотеку, что и CMS</a>-страницы. Библиотека включена и загружается автоматически на страницах панели управления.</p><h2 id="ajax-обработчики-панели-управления"><a href="#ajax-обработчики-панели-управления" class="header-anchor">#</a> AJAX-обработчики панели управления</h2><p>AJAX-обработчики панели управления могут быть определены в классе контроллера или виджетах. В классе контроллера AJAX-обработчики определяются как публичные методы с именами, начинающимися со строки &quot;on&quot;: <strong>onCreateTemplate</strong>, <strong>onGetTemplateList</strong> и т.д.</p><p>AJAX-обработчики панели управления могут возвращать массив данных, выбрасывать исключение или перенаправлять на другую страницу. Вы можете использовать <code>$this-&gt;vars</code> для установки переменных и метод контроллера <code>makePartial</code> для рендеринга частичного представления и возврата его содержимого как части данных ответа.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onOpenTemplate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;someVar&#39;</span><span class="token punctuation">)</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;someValue&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ApplicationException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Invalid value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;partialContents&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;some-partial&#39;</span><span class="token punctuation">)</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="вызов-ajax-запросов"><a href="#вызов-ajax-запросов" class="header-anchor">#</a> Вызов AJAX-запросов</h3><p>AJAX-запрос может быть вызван через API атрибутов данных или JavaScript API. Подробнее см. <a href="./../ajax/introduction.html">фронтенд AJAX-библиотеку</a>. Следующий пример показывает, как вызвать запрос кнопкой в панели управления.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDoSomething<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Do Something
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="ajax-обработчики-поведении"><a href="#ajax-обработчики-поведении" class="header-anchor">#</a> AJAX-обработчики поведений</h2><p>Поскольку поведения объединяют свои методы с родительским контроллером, все AJAX-обработчики, определённые в поведении, доступны контроллеру. В некоторых случаях вы можете захотеть переопределить AJAX-обработчик в контроллере — для этого вызовите метод <code>asExtension</code>.</p><p>AJAX-обработчик контроллера имеет приоритет, затем запрашивается поведение <code>Backend\\Behaviors\\FormController</code> и вызывается его обработчик.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onDoSomething</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Custom logic here</span>
    <span class="token comment">// ...</span>

    <span class="token comment">// Call the extension handler</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">doSomething</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="ajax-обработчики-виджетов"><a href="#ajax-обработчики-виджетов" class="header-anchor">#</a> AJAX-обработчики виджетов</h2><p>Виджеты реализуют тот же AJAX-подход, что и контроллеры панели управления. AJAX-обработчики — это публичные методы класса виджета с именами, начинающимися с префикса <strong>on</strong>. Единственное отличие между AJAX-обработчиками виджета и контроллера панели управления в том, что для ссылки на обработчик в частичных представлениях виджета следует использовать метод виджета <code>getEventHandler</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>javascript:;<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getEventHandler</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;onPaginate&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">title</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Next page<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Next<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>При вызове из класса виджета или частичного представления AJAX-обработчик будет нацелен на сам виджет. Например, если виджет использует псевдоним <strong>mywidget</strong>, обработчик будет вызван как <code>mywidget::onName</code>. Код выше выведет следующее значение атрибута:</p><div class="language-html extra-class"><pre class="language-html"><code>data-request=&quot;mywidget::onPaginate&quot;
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../cms/ajax/introduction.html">Руководство по AJAX-фреймворку</a></li></ul></div>`,19))])}const v=p(i,[["render",r]]);export{x as __pageData,v as default};
